/* ===== messengercompose.css ===========================================
  == Styles for the main Messenger Compose window.
  ======================================================================= */

@import url("chrome://messenger/skin/messenger.css");
@import url("chrome://messenger/skin/shared/messengercompose.css");

@namespace html url("http://www.w3.org/1999/xhtml");

:root[lwtheme] #mail-menubar {
  color: inherit;
}

#compose-toolbox {
  border-block-end: 1px solid var(--chrome-content-separator-color);
}

:root:not([lwtheme]) #composeToolbar2 {
  appearance: none;
}

/* ::::: special toolbar colors ::::: */

#subjectLabel {
  margin-block-end: 0;
  margin-inline-end: 6px;
}

/* ::::: autocomplete icons ::::: */

.autocomplete-richlistitem[type$="-abook"] > .ac-site-icon {
  display: flex;
  margin: 1px 5px;
}

#composeContentBox {
  background-color: -moz-dialog;
  box-shadow: 0 1px 4px rgba(0, 0, 0, 0.2) inset;

  &:-moz-window-inactive {
    box-shadow: 0 1px 4px rgba(0, 0, 0, 0.1) inset;
  }
}

#MsgHeadersToolbar {
  appearance: none !important;
  text-shadow: none;
  padding-block-start: 7px;
}

